INSERT OR IGNORE INTO survey_log (at, key, w, x, y, d, s, initials)
WITH RECURSIVE k(j) AS (SELECT 1 UNION ALL SELECT j + 1 FROM k WHERE j < 867),
picks AS MATERIALIZED (SELECT h.hour * 3600000 + abs(random() % 3600000) AS at, abs(random() % 2500) AS p,
  CASE WHEN abs(random() % 5) = 0 THEN -1 ELSE CAST(600 * (abs(random() % 1000000) / 1000000.0)
    * (abs(random() % 1000000) / 1000000.0) AS INTEGER) END AS q
  FROM seed_hours h JOIN k ON k.j <= h.n
  WHERE h.hour >= 493848 AND h.hour < 493920)
SELECT picks.at, p.key, p.w, p.x, p.y, p.d, 0, COALESCE(n.initials, '')
FROM picks JOIN seed_pool p ON p.i = picks.p LEFT JOIN seed_initials n ON n.i = picks.q;
INSERT OR IGNORE INTO survey_log (at, key, w, x, y, d, s, initials)
WITH RECURSIVE k(j) AS (SELECT 1 UNION ALL SELECT j + 1 FROM k WHERE j < 867),
picks AS MATERIALIZED (SELECT h.hour * 3600000 + abs(random() % 3600000) AS at, abs(random() % 2500) AS p,
  CASE WHEN abs(random() % 5) = 0 THEN -1 ELSE CAST(600 * (abs(random() % 1000000) / 1000000.0)
    * (abs(random() % 1000000) / 1000000.0) AS INTEGER) END AS q
  FROM seed_hours h JOIN k ON k.j <= h.n
  WHERE h.hour >= 493920 AND h.hour < 493992)
SELECT picks.at, p.key, p.w, p.x, p.y, p.d, 0, COALESCE(n.initials, '')
